		const REF_IMAGE_MAX_BYTES = 10 * 1024 * 1024;
		const CONVERSATION_IMAGE_MAX_DIMENSION = 2e3;
		const CONVERSATION_IMAGE_JPEG_QUALITY = .9;
		const PREVIEW_SCALE_MIN = .5;
		const PREVIEW_SCALE_MAX = 3;
